"use strict";

// Complete the row-14 raw Smith proof from the exact source-operation column
// ancestry regenerated by row14_terminal_class_witness_coordinator.cjs.
// Matrices are row-major here.  The coordinator's `rawToTerminal` consists of
// terminal columns expressed in the 806 raw relation columns, so each emitted
// ancestry vector is already one row of a left relation transform.

const gap = require("./row14_raw_relation_smith_gap.cjs");
const output = require("./class_unit_output_evidence_v2.cjs");

const SCHEMA = "sagejs.pari-class-group/row14-full-raw-smith-ancestry-v1";
const ANCESTRY_SCHEMA =
  "sagejs.pari-class-group/row14-full-column-ancestry-v1";
const ACCEPTED_OWNER_SHA256 =
  "9a24358fc2846778c7940df1be206a18048780375a60f6e9edf039b36c770b65";
const FACTOR_METADATA_SHA256 =
  "cca3c14630fc91a407a052bbc7fb2799b5e95bce79f1948fc422ca39cda07684";
const TERMINAL_STATE = Object.freeze(["3", "10", "796", "0", "7", "0", "0", "806", "0"]);

class Row14FullRawSmithAncestryFailure extends Error {}
function fail(message) { throw new Row14FullRawSmithAncestryFailure(message); }
function canonicalIntegers(values, length, name) {
  if (!Array.isArray(values) || values.length !== length) fail(`${name} changed shape`);
  return values.map((value, index) => {
    if (typeof value !== "string") fail(`${name}[${index}] is not a string`);
    let parsed;
    try { parsed = BigInt(value); }
    catch { fail(`${name}[${index}] is not an integer`); }
    if (parsed.toString() !== value) fail(`${name}[${index}] is not canonical`);
    return parsed;
  });
}

function buildRow14FullRawSmithAncestry(raw, ancestryInput) {
  const partial = gap.buildRow14RawSmithGap(raw);
  const ancestry = typeof ancestryInput === "string" || Buffer.isBuffer(ancestryInput)
    ? JSON.parse(ancestryInput.toString()) : structuredClone(ancestryInput);
  if (!ancestry || ancestry.schema !== ANCESTRY_SCHEMA ||
      JSON.stringify(ancestry.rawToTerminalShape) !== "[806,806]" ||
      ancestry.source?.acceptedOwnerSha256 !== ACCEPTED_OWNER_SHA256 ||
      ancestry.source?.factorMetadataSha256 !== FACTOR_METADATA_SHA256 ||
      ancestry.source?.rawRelationRecordsSha256 !== partial.source.relationMatrixSha256 ||
      JSON.stringify(ancestry.source?.terminalState) !== JSON.stringify(TERMINAL_STATE) ||
      ancestry.state?.backend !== "source-hnfspec-hnfadd-reverse-replay" ||
      ancestry.state?.selectedColumns !== gap.ROWS ||
      ancestry.state?.relationCollectionRerun !== false ||
      ancestry.state?.frozenW0UsedAsInput !== false) {
    fail("full ancestry authority changed");
  }
  const terminal = canonicalIntegers(ancestry.rawToTerminal,
    gap.ROWS * gap.ROWS, "terminal ancestry");

  // Terminal columns 10..805 are the 796 final identity/tail columns.  Put
  // them first, followed by the three normalized class rows and the seven
  // kernel rows, matching the diagonal convention in the existing proof.
  const left = [];
  for (let row = 10; row < gap.ROWS; row += 1) {
    left.push(...terminal.slice(row * gap.ROWS, (row + 1) * gap.ROWS));
  }
  for (let row = 0; row < gap.CLASS; row += 1) {
    for (let rawRelation = 0; rawRelation < gap.ROWS; rawRelation += 1) {
      let value = 0n;
      for (let inner = 0; inner < gap.CLASS; inner += 1) {
        value += gap.SMALL_LEFT[row * gap.CLASS + inner] *
          terminal[(7 + inner) * gap.ROWS + rawRelation];
      }
      left.push(value);
    }
  }
  left.push(...terminal.slice(0, gap.KERNEL * gap.ROWS));
  if (left.length !== gap.ROWS * gap.ROWS) fail("left transform construction failed");

  const material = {
    d: partial.material.d,
    u: left.map(String),
    v: partial.material.v,
  };
  return Object.freeze({
    schema: SCHEMA,
    source: {
      ...partial.source,
      acceptedOwnerSha256: ACCEPTED_OWNER_SHA256,
      factorMetadataSha256: FACTOR_METADATA_SHA256,
      fullAncestrySha256: output.sha256Canonical(ancestry.rawToTerminal),
    },
    rawShape: partial.rawShape,
    shapes: {
      d: [String(gap.ROWS), String(gap.COLUMNS)],
      u: [String(gap.ROWS), String(gap.ROWS)],
      v: [String(gap.COLUMNS), String(gap.COLUMNS)],
    },
    diagonalFactors: partial.diagonalFactors,
    classNumber: partial.classNumber,
    invariantFactors: partial.invariantFactors,
    material,
    materialSha256: {
      d: output.sha256Canonical(material.d),
      u: output.sha256Canonical(material.u),
      v: output.sha256Canonical(material.v),
    },
    completed: {
      fullDiagonal: true,
      fullLeftTransform: true,
      fullRightTransform: true,
      fullSmithIdentity: true,
    },
    qualifiedTiming: false,
  });
}

module.exports = Object.freeze({
  ACCEPTED_OWNER_SHA256, ANCESTRY_SCHEMA, FACTOR_METADATA_SHA256, SCHEMA,
  Row14FullRawSmithAncestryFailure, buildRow14FullRawSmithAncestry,
});
